/* ---- s2_policy.c implementation ---- */

static void dense(const float *x, float *y, const float *w,
                  const float *bias, unsigned ni, unsigned no, int relu) {
    unsigned i, j;
    for (i = 0; i < no; ++i) {
        float v = 0.0f;
        for (j = 0; j < ni; ++j) v += w[i * ni + j] * x[j];
        v += bias[i];
        y[i] = relu && v < 0.0f ? 0.0f : v;
    }
}

int s2_policy_forward(const float obs[65], float raw[2], S2PolicyWorkspace *work) {
    unsigned i;
    if (!raw) return -1;
    raw[0] = raw[1] = 0.0f;
    if (!obs || !work) return -1;
    for (i = 0; i < 65; ++i) {
        if (!isfinite(obs[i])) return -1;
        work->normalized[i] = (obs[i] - s2_norm_mean[i]) / (s2_norm_std[i] + s2_norm_eps[0]);
        if (!isfinite(work->normalized[i])) return -1;
    }
    dense(work->normalized, work->a, s2_actor_0_weight, s2_actor_0_bias, 65, 256, 1);
    dense(work->a, work->b, s2_actor_2_weight, s2_actor_2_bias, 256, 128, 1);
    dense(work->b, work->a, s2_actor_4_weight, s2_actor_4_bias, 128, 64, 1);
    dense(work->a, raw, s2_actor_6_weight, s2_actor_6_bias, 64, 2, 0);
    for (i = 0; i < 2; ++i) if (!isfinite(raw[i])) {
        raw[0] = raw[1] = 0.0f; return -1;
    }
    return 0;
}

/* ---- s2_controller.c implementation ---- */

static float clip(float x, float lo, float hi) { return fminf(hi, fmaxf(lo, x)); }
static int finite_array(const float *a, unsigned n) {
    unsigned i; for (i = 0; i < n; ++i) if (!isfinite(a[i])) return 0; return 1;
}
void s2_config_default(S2Config *c) {
    if (!c) return;
    c->gyro_mode = S2_GYRO_QUAT_DIFFERENCE;
    c->torque_limit_nm = 20.0f; c->slew_rate_nm_s = 0.0f; c->warmup_ticks = 10;
}
void s2_controller_reset(S2Controller *s) { if (s) memset(s, 0, sizeof(*s)); }
int s2_controller_commit_command(S2Controller *s, const float a[2]) {
    if (!s || !a || !finite_array(a, 2) || fabsf(a[0]) > 20 || fabsf(a[1]) > 20) return -1;
    memcpy(s->previous_command, a, 2 * sizeof(float)); return 0;
}
S2Status s2_controller_step(S2Controller *s, const S2Config *c,
                           const S2Input *in, S2Output *out) {
    float q[4], norm2 = 0, gyro[3] = {0,0,0}, gx, gy, gz, dot = 0;
    unsigned i;
    if (!out) { s2_controller_reset(s); return S2_BAD_INPUT; }
    memset(out, 0, sizeof(*out));
    if (!s || !c || !in) { s2_controller_reset(s); return S2_BAD_INPUT; }
    if ((c->gyro_mode != S2_GYRO_QUAT_DIFFERENCE && c->gyro_mode != S2_GYRO_SENSOR) ||
        !isfinite(c->torque_limit_nm) || c->torque_limit_nm < 0 || c->torque_limit_nm > 20 ||
        !isfinite(c->slew_rate_nm_s) || c->slew_rate_nm_s < 0) {
        s2_controller_reset(s); return S2_BAD_CONFIG;
    }
    if (!in->enabled) { s2_controller_reset(s); return S2_DISABLED; }
    if (!in->sensors_valid || !finite_array(in->hip_rad,2) || !finite_array(in->hip_rad_s,2) ||
        !finite_array(in->quat_wb,4) || !isfinite(in->measured_dt_s) ||
        fabsf(in->measured_dt_s - S2_DT_S) > 0.001f ||
        (c->gyro_mode == S2_GYRO_SENSOR && !finite_array(in->gyro_body_rad_s,3))) {
        s2_controller_reset(s); return S2_BAD_INPUT;
    }
    for (i=0;i<4;++i) norm2 += in->quat_wb[i]*in->quat_wb[i];
    if (!isfinite(norm2) || norm2 < 0.81f || norm2 > 1.21f) {
        s2_controller_reset(s); return S2_BAD_INPUT;
    }
    /* Normalize valid AHRS quaternion; source quaternions are already unit. */
    for (i=0;i<4;++i) { q[i]=in->quat_wb[i]/sqrtf(norm2); dot+=q[i]*s->previous_quat[i]; }
    if (s->quat_initialized && dot<0) for (i=0;i<4;++i) q[i]=-q[i];
    if (c->gyro_mode == S2_GYRO_SENSOR) memcpy(gyro,in->gyro_body_rad_s,sizeof(gyro));
    else if (s->quat_initialized) {
        const float *p=s->previous_quat;
        /* 2/dt * vector(conjugate(previous) * current), matching Python. */
        gyro[0]=100.0f*(p[0]*q[1]-p[1]*q[0]-p[2]*q[3]+p[3]*q[2]);
        gyro[1]=100.0f*(p[0]*q[2]+p[1]*q[3]-p[2]*q[0]-p[3]*q[1]);
        gyro[2]=100.0f*(p[0]*q[3]-p[1]*q[2]+p[2]*q[1]-p[3]*q[0]);
    }
    memcpy(s->previous_quat,q,sizeof(q)); s->quat_initialized=1;
    memmove(s->history,s->history+6,54*sizeof(float));
    for(i=0;i<2;++i) {
        s->history[54+i]=in->hip_rad[i]/S2_PI;
        s->history[56+i]=in->hip_rad_s[i]/(4.0f*S2_PI);
        s->history[58+i]=s->previous_command[i]/40.0f;
    }
    memcpy(out->obs,s->history,sizeof(s->history));
    /* transpose(R_WB) * [0,0,-1]. */
    gx=2.0f*(q[0]*q[2]-q[1]*q[3]);
    gy=-2.0f*(q[2]*q[3]+q[0]*q[1]);
    gz=-1.0f+2.0f*(q[1]*q[1]+q[2]*q[2]);
    out->obs[60]=atan2f(-gy,-gz)/S2_PI;
    out->obs[61]=atan2f(gx,-gz)/S2_PI;
    for(i=0;i<3;++i) out->obs[62+i]=gyro[i]/(4.0f*S2_PI);
    if (s->ticks<c->warmup_ticks) {
        s->previous_command[0]=s->previous_command[1]=0;
        ++s->ticks; return S2_WARMUP;
    }
    if (s2_policy_forward(out->obs,out->raw,&s->work)) {
        memset(out,0,sizeof(*out)); s2_controller_reset(s); return S2_NUMERIC_ERROR;
    }
    for(i=0;i<2;++i) {
        float a=20.0f*clip(out->raw[i],-1,1);
        out->requested_nm[i]=a;
        a=clip(a,-c->torque_limit_nm,c->torque_limit_nm);
        if(c->slew_rate_nm_s>0) {
            float delta=c->slew_rate_nm_s*S2_DT_S;
            a=s->previous_command[i]+clip(a-s->previous_command[i],-delta,delta);
        }
        out->command_nm[i]=clip(a,-c->torque_limit_nm,c->torque_limit_nm);
    }
    s2_controller_commit_command(s,out->command_nm);
    if(s->ticks<UINT32_MAX) ++s->ticks;
    return S2_OK;
}

/* ---- s2_port.c implementation ---- */
static int unit_quat(const float q[4]) {
    float n=0; unsigned i;
    for(i=0;i<4;++i) { if(!isfinite(q[i])) return 0; n+=q[i]*q[i]; }
    return isfinite(n) && fabsf(n-1.0f)<0.001f;
}
static int valid_config(const S2PortConfig *c) {
    unsigned i;
    if(!c || !c->calibration_confirmed || !unit_quat(c->quat_sb)) return 0;
    for(i=0;i<2;++i) if((c->encoder_sign[i]!=1 && c->encoder_sign[i]!=-1) ||
        (c->motor_sign[i]!=1 && c->motor_sign[i]!=-1) || !isfinite(c->encoder_zero_rad[i])) return 0;
    return 1;
}
void s2_port_config_default(S2PortConfig *c) {
    if(!c) return;
    memset(c,0,sizeof(*c)); c->quat_sb[0]=1;
    c->encoder_sign[0]=c->encoder_sign[1]=1;
    c->motor_sign[0]=c->motor_sign[1]=1;
}
int s2_port_map_input(const S2PortConfig *c,const S2HardwareInput *h,S2Input *m) {
    const float *a,*b; unsigned i; float w,x,y,z,n=0,r[9];
    if(!m) return -1;
    memset(m,0,sizeof(*m));
    if(!valid_config(c) || !h || !h->sensors_valid) return -1;
    for(i=0;i<4;++i) { if(!isfinite(h->quat_ws[i])) return -1; n+=h->quat_ws[i]*h->quat_ws[i]; }
    if(!isfinite(n) || n<0.81f || n>1.21f) return -1;
    for(i=0;i<2;++i) if(!isfinite(h->encoder_joint_rad[i]) || !isfinite(h->encoder_joint_rad_s[i])) return -1;
    for(i=0;i<3;++i) if(!isfinite(h->gyro_sensor_rad_s[i])) return -1;
    if(!isfinite(h->measured_dt_s) || fabsf(h->measured_dt_s-S2_DT_S)>0.001f) return -1;
    a=h->quat_ws; b=c->quat_sb;
    m->quat_wb[0]=a[0]*b[0]-a[1]*b[1]-a[2]*b[2]-a[3]*b[3];
    m->quat_wb[1]=a[0]*b[1]+a[1]*b[0]+a[2]*b[3]-a[3]*b[2];
    m->quat_wb[2]=a[0]*b[2]-a[1]*b[3]+a[2]*b[0]+a[3]*b[1];
    m->quat_wb[3]=a[0]*b[3]+a[1]*b[2]-a[2]*b[1]+a[3]*b[0];
    for(i=0;i<2;++i) {
        m->hip_rad[i]=c->encoder_sign[i]*(h->encoder_joint_rad[i]-c->encoder_zero_rad[i]);
        m->hip_rad_s[i]=c->encoder_sign[i]*h->encoder_joint_rad_s[i];
        if(!isfinite(m->hip_rad[i]) || !isfinite(m->hip_rad_s[i])) { memset(m,0,sizeof(*m));return -1; }
    }
    w=b[0];x=b[1];y=b[2];z=b[3];
    r[0]=1-2*(y*y+z*z);r[1]=2*(x*y-z*w);r[2]=2*(x*z+y*w);
    r[3]=2*(x*y+z*w);r[4]=1-2*(x*x+z*z);r[5]=2*(y*z-x*w);
    r[6]=2*(x*z-y*w);r[7]=2*(y*z+x*w);r[8]=1-2*(x*x+y*y);
    for(i=0;i<3;++i) {
        m->gyro_body_rad_s[i]=r[i]*h->gyro_sensor_rad_s[0]+r[3+i]*h->gyro_sensor_rad_s[1]+r[6+i]*h->gyro_sensor_rad_s[2];
        if(!isfinite(m->gyro_body_rad_s[i])) { memset(m,0,sizeof(*m));return -1; }
    }
    m->measured_dt_s=h->measured_dt_s;m->enabled=h->enabled;m->sensors_valid=1;
    return 0;
}
int s2_port_map_output(const S2PortConfig *c,const float a[2],float driver[2]) {
    if(!driver) return -1;
    driver[0]=driver[1]=0;
    if(!valid_config(c) || !a || !isfinite(a[0]) || !isfinite(a[1]) ||
       fabsf(a[0])>20 || fabsf(a[1])>20) return -1;
    driver[0]=c->motor_sign[0]*a[0];driver[1]=c->motor_sign[1]*a[1];return 0;
}

/* ---- s2_example.c implementation ---- */
static S2Controller controller;
static S2Output output;
S2PortConfig s2_board_config;
S2Config s2_app_config;
void s2_app_init(void) {
    s2_controller_reset(&controller);
    s2_config_default(&s2_app_config);
    /* Hardware gyro is preferred for integration; differs from quaternion
     * finite-difference parity mode. Verify actual gyro units/axis signs. */
    s2_app_config.gyro_mode=S2_GYRO_SENSOR;
    s2_port_config_default(&s2_board_config);
}
S2Status s2_app_tick_50hz(const S2HardwareInput *input,float driver_joint_nm[2]) {
    S2Input model; S2Status status;
    if(!driver_joint_nm) { s2_controller_reset(&controller);return S2_BAD_INPUT; }
    driver_joint_nm[0]=driver_joint_nm[1]=0;
    if(s2_port_map_input(&s2_board_config,input,&model)) {
        s2_controller_reset(&controller);return S2_BAD_INPUT;
    }
    status=s2_controller_step(&controller,&s2_app_config,&model,&output);
    if(status!=S2_OK) return status;
    if(s2_port_map_output(&s2_board_config,output.command_nm,driver_joint_nm)) {
        s2_controller_reset(&controller);return S2_BAD_INPUT;
    }
    return status;
}

